contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(address spender, uint256 val) public payable {
        require(spender != address(0));

        // read allowance before
        uint256 beforeAllow = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        // attempt to approve; capture whether it reverted
        bool didRevert;
        c.approve(spender, val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // read allowance after
        uint256 afterAllow = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        // If approve reverted, allowance must remain unchanged; otherwise it must equal the requested value.
        assert( (didRevert && afterAllow == beforeAllow) || (!didRevert && afterAllow == val) );
    }

    receive() external payable {}
}

